import pandas as pd

def find_subordinates(employees: pd.DataFrame) -> pd.DataFrame:
    if employees.empty:
        return pd.DataFrame(columns=['subordinate_id', 'subordinate_name', 'hierarchy_level', 'salary_difference'])

    ceo_row = employees[employees['manager_id'].isna()]
    if ceo_row.empty:
        return pd.DataFrame(columns=['subordinate_id', 'subordinate_name', 'hierarchy_level', 'salary_difference'])

    ceo_id = ceo_row.iloc[0]['employee_id']
    ceo_salary = ceo_row.iloc[0]['salary']

    results = []
    # BFS traversal by hierarchy level
    current_level = 1
    current_managers = [ceo_id]

    while current_managers:
        subs = employees[employees['manager_id'].isin(current_managers)]
        if subs.empty:
            break
        for _, row in subs.iterrows():
            results.append({
                'subordinate_id': int(row['employee_id']),
                'subordinate_name': row['employee_name'],
                'hierarchy_level': current_level,
                'salary_difference': int(row['salary'] - ceo_salary)
            })
        current_managers = subs['employee_id'].tolist()
        current_level += 1

    if not results:
        return pd.DataFrame(columns=['subordinate_id', 'subordinate_name', 'hierarchy_level', 'salary_difference'])

    res_df = pd.DataFrame(results)
    return res_df.sort_values(by=['hierarchy_level', 'subordinate_id'], ascending=[True, True])
